class Solution {
  public int[] shortestDistanceAfterQueries(int n, int[][] queries) {
    int[] next = new int[n]; // next[i]: where the shortest route moves on from city i
    for (int i = 0; i < n; i++) next[i] = i + 1;
    int distance = n - 1;
    int[] answer = new int[queries.length];
    for (int q = 0; q < queries.length; q++) {
      int u = queries[q][0], v = queries[q][1];
      if (next[u] < v) {
        // roads never cross, so every city strictly between u and v on the route is skipped
        int city = next[u];
        while (city < v) {
          int after = next[city];
          next[city] = v;
          city = after;
          distance--;
        }
        next[u] = v;
      }
      answer[q] = distance;
    }
    return answer;
  }
}
